337					t.Fatalf("read must report corruption, got %v", err)
338				} else if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "version") {
339					t.Errorf("error must name record 1 and the version field, got: %v", err)
340				}
