345					t.Errorf("history must refuse corrupt data, got %v", err)
346				}
347				if _, err := store.Health("bad", receive, "1.26.0", 0); err == nil || !IsCorrupt(err) {
348					t.Errorf("health must refuse corrupt data, got %v", err)
349				}
350				if _, err := store.HealthSince("bad", receive, "1.26.0", 0, 1); err == nil || !IsCorrupt(err) {
351					t.Errorf("health with baseline must refuse corrupt data, got %v", err)
352				}
