362					t.Errorf("submit touching corrupt node must fail with corruption, got new=%d dup=%d err=%v", newC, dupC, err)
363				}
364				if newC != 0 || dupC != 0 {
365					t.Errorf("counts = %d/%d, want 0/0", newC, dupC)
366				}
367				after, err := os.ReadFile(path)
368				if err != nil {
369					t.Fatal(err)
370				}
371				if string(after) != string(before) {
372					t.Errorf("corrupt file was overwritten by the rejected submit")
373				}
374				hist, err := store.History("good")
375				if err != nil || len(hist) != 1 {
376					t.Errorf("healthy node gained records from the rejected batch: %v %+v", err, hist)
377				}
378	
379				// The healthy node's queries are unaffected.
380				r, err := store.Health("good", receive, "1.26.0", 0)
381				if err != nil || r.Status != "online" {
382					t.Errorf("healthy node health changed: %v %+v", err, r)
383				}
384			})
385		}
386	}
