3	// Command-line regression tests for health queries over disconnected and
4	// replayed telemetry. The domain rules have focused tests in package
5	// edgefleet; these tests pin what a user actually sees through the real
6	// `edgefleet heartbeat health` entry point:
7	//
8	//   - when a node stores a stale greater-seq record and a fresh smaller-seq
9	//     record that arrived in either order, the health line must be built
10	//     entirely from the greatest seq — offline, with that record's time,
11	//     version, height and cumulative missed — never spliced with the fresh
12	//     record and never flipped online by its newer collection time;
13	//   - a late backfill or a verbatim duplicate of the smaller seq submitted at
14	//     an even later receive time changes neither the result nor the saved
15	//     file;
16	//   - the online edge is exact at nanosecond precision (60s online, 60s+1ns
17	//     offline) while the terminal keeps printing collection time as whole
18	//     seconds, and timezone re-spellings of the same instants agree;
19	//   - a missed-since baseline changes only the alarm quantity: the first line
20	//     still shows the greatest-seq record and its cumulative count, and the
21	//     baseline never decides online status;
22	//   - a query time earlier than the greatest-seq record's collection time is
23	//     an error (non-zero exit, reason on stderr, nothing on stdout) for both
24	//     plain and baseline queries, even though a smaller-seq record had already
25	//     been collected by then; offline itself is a successful query that
26	//     exits zero;
27	//   - no query, failed query or duplicate submission rewrites the saved
28	//     heartbeats.
29	
30	import (
31		"os"
32		"strings"
33		"testing"
34	)
35	
36	const (
37		// The disordered scenario uses a fixed query instant (same as the other
38		// CLI tests) and two records:
39		//
40		//	seq 10 collected 11:58:00 (2 minutes old, offline), version 1.25.0,
41		//	        height 1000, cumulative missed 5;
42		//	seq  5 collected 11:59:50 (10 seconds old, fresh), version 1.26.0,
43		//	        height 900, cumulative missed 2.
44		reconnectNode         = "backfill"
45		reconnectLatestLine   = "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0 missed duties above tolerance]"
46		reconnectStaleReceive = "2026-10-01T11:58:30Z"
47	)
48	
49	const reconnectStaleRecord = `{"node":"backfill","seq":10,"collected_at":"2026-10-01T11:58:00Z","version":"1.25.0","height":1000,"missed":5}`
50	const reconnectFreshRecord = `{"node":"backfill","seq":5,"collected_at":"2026-10-01T11:59:50Z","version":"1.26.0","height":900,"missed":2}`
51	
52	// submitWithReceive runs one submit command with an explicit receive time.
53	func submitWithReceive(t *testing.T, dir, json, receiveAt string) {
54		t.Helper()
55		out, errOut, code := runCLI(t, dir, json,
56			"heartbeat", "submit", "--data-dir", dir, "--receive-time", receiveAt)
57		if code != 0 {
58			t.Fatalf("submit at %s exited %d: stderr=%q stdout=%q", receiveAt, code, errOut, out)
59		}
60	}
61	
62	// healthQueryAt runs a health command with an explicit query instant.
63	func healthQueryAt(t *testing.T, dir, at string, args ...string) (string, string, int) {
64		t.Helper()
65		full := append([]string{"heartbeat", "health", "--data-dir", dir, "--at", at}, args...)
66		return runCLI(t, dir, "", full...)
67	}
68	
69	// seedReconnectStored stores the disordered pair in the "natural outage"
70	// arrival order: the stale seq-10 record was received during the outage
71	// (90 seconds after it was collected), and the fresh seq-5 record is only
72	// backfilled when the node reconnects at the query instant.
73	func seedReconnectStored(t *testing.T, dir string) {
74		t.Helper()
75		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", reconnectStaleReceive)
76		submitWithReceive(t, dir, "["+reconnectFreshRecord+"]", cliReceiveAt)
77	}
78	
79	// seedReconnectReversed stores the same pair with the stale greatest-seq
80	// record physically arriving after the fresh smaller-seq record.
81	func seedReconnectReversed(t *testing.T, dir string) {
82		t.Helper()
83		submitWithReceive(t, dir, "["+reconnectFreshRecord+"]", cliReceiveAt)
84		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", cliReceiveAt)
85	}
86	
87	// assertReconnectHealthLine checks the single output line is the exact one
88	// produced from the seq-10 record alone. A selector driven by receive order,
89	// newest collection time, whole-second display, or field splicing would
90	// differ: the fresh seq-5 record would show status=online, version=1.26.0
91	// (no skew), height=900 and missed=2 (no alarm at tolerance 4).
92	func assertReconnectHealthLine(t *testing.T, out, errOut string, code int) {
93		t.Helper()
94		if code != 0 {
95			t.Fatalf("offline is a successful query and must exit 0, got %d: stderr=%q", code, errOut)
96		}
97		if errOut != "" {
98			t.Errorf("health findings belong on stdout; stderr must be empty, got %q", errOut)
99		}
100		lines := outputLines(out)
101		if len(lines) != 1 {
102			t.Fatalf("want exactly one health line, got %d: %q", len(lines), out)
103		}
104		if lines[0] != reconnectLatestLine {
105			t.Errorf("health line = %q\nwant            %q", lines[0], reconnectLatestLine)
106		}
107	}
108	
109	// TestCLIHealthReplayedRecordsGreatestSeqDrivesStatus saves the same two
110	// records in both arrival orders and requires the byte-identical health line,
111	// built entirely from the greatest seq.
112	func TestCLIHealthReplayedRecordsGreatestSeqDrivesStatus(t *testing.T) {
113		var seen []string
114		for _, seed := range []struct {
115			name string
116			fn   func(*testing.T, string)
117		}{
118			{"stale greatest seq received first", seedReconnectStored},
119			{"stale greatest seq received last", seedReconnectReversed},
120		} {
121			t.Run(seed.name, func(t *testing.T) {
122				dir := t.TempDir()
123				seed.fn(t, dir)
124				out, errOut, code := healthQueryAt(t, dir, cliQueryAt,
125					"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
126				assertReconnectHealthLine(t, out, errOut, code)
127				seen = append(seen, out)
128	
129				// History keeps both gapped seqs ascending, each intact.
130				lines := historyLines(t, dir, reconnectNode)
131				if len(lines) != 2 {
132					t.Fatalf("history = %q, want two records", lines)
133				}
134				if lines[0] != "node=backfill seq=5 collected_at=2026-10-01T11:59:50Z version=1.26.0 height=900 missed=2" {
135					t.Errorf("history line 1 = %q", lines[0])
136				}
137				if lines[1] != "node=backfill seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5" {
138					t.Errorf("history line 2 = %q", lines[1])
139				}
140			})
141		}
142		if len(seen) == 2 && seen[0] != seen[1] {
143			t.Errorf("arrival order changed the output:\n%s\nvs\n%s", seen[0], seen[1])
144		}
145	}
146	
147	// TestCLIHealthLateDuplicateResubmitChangesNothing replays the smaller-seq
148	// record at a later receive time, first already covered by the stored pair
149	// via a fresh backfill, then as a verbatim duplicate, and checks the latest
150	// telemetry collection time and the offline judgement never move.
151	func TestCLIHealthLateDuplicateResubmitChangesNothing(t *testing.T) {
152		dir := t.TempDir()
153		// Only the stale greatest-seq record is known initially.
154		submitWithReceive(t, dir, "["+reconnectStaleRecord+"]", reconnectStaleReceive)
155	
156		out, _, code := healthQueryAt(t, dir, cliQueryAt,
157			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
158		if code != 0 || !strings.Contains(out, "seq=10") || !strings.Contains(out, "status=offline") {
159			t.Fatalf("initial query: code=%d out=%q", code, out)
160		}
161	
162		// The node reconnects later and backfills the smaller seq for the first
163		// time. Its receive time is later, but the latest record stays seq 10.
164		later := "2026-10-01T12:02:00Z"
165		submitOut, errOut, submitCode := runCLI(t, dir, "["+reconnectFreshRecord+"]",
166			"heartbeat", "submit", "--data-dir", dir, "--receive-time", later)
167		if submitCode != 0 {
168			t.Fatalf("late backfill exited %d: stderr=%q stdout=%q", submitCode, errOut, submitOut)
169		}
170		if !strings.Contains(submitOut, "new=1 duplicate=0") {
171			t.Errorf("first backfill counts = %q, want new=1 duplicate=0", strings.TrimSpace(submitOut))
172		}
173		out, _, code = healthQueryAt(t, dir, later,
174			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
175		assertReconnectHealthLineLater(t, out, code, later)
176	
177		// Re-submitting the same record at yet another receive time is a duplicate
178		// and must not refresh the latest collection time or change any judgement.
179		evenLater := "2026-10-01T12:03:00Z"
180		submitOut, _, submitCode = runCLI(t, dir, "["+reconnectFreshRecord+"]",
181			"heartbeat", "submit", "--data-dir", dir, "--receive-time", evenLater)
182		if submitCode != 0 {
183			t.Fatalf("duplicate replay exited %d: stderr=%q", submitCode, errOut)
184		}
185		if !strings.Contains(submitOut, "new=0 duplicate=1") {
186			t.Errorf("duplicate replay counts = %q, want new=0 duplicate=1", strings.TrimSpace(submitOut))
187		}
188		out, _, code = healthQueryAt(t, dir, evenLater,
189			"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
190		assertReconnectHealthLineLater(t, out, code, evenLater)
191	}
