193	// assertReconnectHealthLineLater is the same seq-10 expectation at a query
194	// instant other than the shared fixture constant; only the printed query frame
195	// changes, the health line does not.
196	func assertReconnectHealthLineLater(t *testing.T, out string, code int, _ string) {
197		t.Helper()
198		if code != 0 {
199			t.Fatalf("query must exit 0, got %d", code)
200		}
201		lines := outputLines(out)
