95	// TestCLISubmitValidUnicodeVersionRoundTrip checks the legal cases keep
96	// working end to end: a literal "�" is valid text the user typed, an escape
97	// spelling of the same text is the same version (a duplicate, not a new
98	// record), and health keeps comparing the expected version exactly.
99	func TestCLISubmitValidUnicodeVersionRoundTrip(t *testing.T) {
100		dir := t.TempDir()
101		bs := "\\"
102	
103		// Literal replacement character in the version: legal text, accepted.
104		out, _, code := runCLI(t, dir,
105			`[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0-�","height":1,"missed":0}]`,
106			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
107		if code != 0 || !strings.Contains(out, "new=1") {
108			t.Fatalf("literal replacement char must be accepted: code=%d out=%q", code, out)
109		}
110	
111		// The same text written as a � escape is the same version: duplicate.
112		out, _, code = runCLI(t, dir,
113			`[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0-`+bs+`uFFFD","height":1,"missed":0}]`,
114			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
115		if code != 0 || !strings.Contains(out, "new=0 duplicate=1") {
116			t.Errorf("escaped form of the same version must be a duplicate: code=%d out=%q", code, out)
117		}
118	
119		// Chinese and an emoji written as a surrogate-pair escape are legal
120		// versions; nothing is restricted to digits and dots.
121		out, _, code = runCLI(t, dir,
122			`[{"node":"n1","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"正式版-`+bs+`uD83D`+bs+`uDE00","height":2,"missed":0}]`,
