139		// skew, any other text is.
140		out, _, code = runCLI(t, dir, "",
141			"heartbeat", "health", "--data-dir", dir, "--node", "n1",
142			"--expected-version", "正式版-😀", "--tolerated-misses", "0", "--at", cliQueryAt)
