150			"heartbeat", "health", "--data-dir", dir, "--node", "n1",
151			"--expected-version", "正式版", "--tolerated-misses", "0", "--at", cliQueryAt)
152		if code != 0 || !strings.Contains(out, "version skew: 正式版-😀 != 正式版") {
153			t.Errorf("different expected version must skew exactly, code=%d out=%q", code, out)
