157	// TestCLIStoredInvalidVersionIsCorrupt exercises the read boundary from the
158	// command line: a saved file whose version cannot decode losslessly is data
159	// corruption even when its checksum matches the replacement-char
160	// interpretation. History, plain health and baseline health all fail
161	// non-zero with nothing on stdout, a submit batch touching the node fails
162	// without overwriting the file, and other nodes keep working.
163	func TestCLIStoredInvalidVersionIsCorrupt(t *testing.T) {
164		f := newFixture(t)
165		bs := "\\"
166	
167		cases := []struct {
168			name   string
169			tamper string // raw version token stored in the file
170		}{
171			{"invalid UTF-8 byte", "1.26.0-" + "\xff"},
172			{"unpaired surrogate escape", "1.26.0-" + bs + "uD83D"},
173		}
174		for _, tc := range cases {
175			t.Run(tc.name, func(t *testing.T) {
176				// The forged checksum hashes the record a lenient reader would
177				// reconstruct: the version rewritten to "1.26.0-�".
178				tampered := `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"` + tc.tamper + `","height":100,"missed":0}]`
179				interpreted := `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0-�","height":100,"missed":0}]`
180				corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(interpreted), tampered))
181				badBefore := readNodeFile(t, f.dir, "bad")
182				monoBefore := readNodeFile(t, f.dir, "mono")
183	
184				// history: non-zero exit, reason on stderr naming the file, the
185				// record and the version field, nothing on stdout.
186				out, errOut, code := runCLI(t, f.dir, "",
187					"heartbeat", "history", "--data-dir", f.dir, "--node", "bad")
188				if code == 0 {
189					t.Errorf("history on corrupt version must exit non-zero; stdout=%q", out)
190				}
191				if out != "" {
192					t.Errorf("history must print no results on corruption, stdout=%q", out)
193				}
194				if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, "version") ||
195					!strings.Contains(errOut, filepath.Base(nodeFileHexPath(f.dir, "bad"))) {
196					t.Errorf("history stderr must name the file, record and version field, got %q", errOut)
197				}
198	
199				// health, plain and with a missed-duty baseline: same contract.
200				for _, extra := range [][]string{
201					{},
202					{"--missed-since-seq", "1"},
203				} {
204					args := append([]string{"--node", "bad", "--expected-version", "1.26.0", "--tolerated-misses", "0"}, extra...)
205					out, errOut, code = health(t, f, args...)
206					if code == 0 {
207						t.Errorf("health %v on corrupt version must exit non-zero; stdout=%q", extra, out)
208					}
209					if out != "" {
210						t.Errorf("health %v must print no results on corruption, stdout=%q", extra, out)
211					}
212					if !strings.Contains(errOut, "version") {
213						t.Errorf("health %v stderr must name the version field, got %q", extra, errOut)
214					}
215				}
216	
217				// A submit batch touching the corrupt node is refused as a whole:
218				// no success line, the corrupt file stays byte-for-byte intact,
219				// and the valid record for a healthy node is not saved either.
220				batch := `[
221				  {"node":"bad","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":101,"missed":0},
222				  {"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15}
223				]`
224				out, errOut, code = runCLI(t, f.dir, batch,
225					"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
226				if code == 0 {
227					t.Errorf("submit touching a corrupt node must fail non-zero; stdout=%q", out)
228				}
229				if strings.Contains(out, "submitted") {
230					t.Errorf("rejected batch must not report success, stdout=%q", out)
231				}
232				if !strings.Contains(errOut, "corruption") || !strings.Contains(errOut, "version") {
233					t.Errorf("submit stderr must explain the corruption, got %q", errOut)
234				}
235				if got := readNodeFile(t, f.dir, "bad"); got != badBefore {
236					t.Errorf("corrupt node file was modified during rejected submit")
237				}
238				if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
239					t.Errorf("healthy node file was rewritten during rejected submit")
240				}
241	
242				// Other nodes keep answering normally.
243				out, _, code = health(t, f,
244					"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
245				if code != 0 || !strings.Contains(out, "node=mono") {
246					t.Errorf("healthy node must still query normally: code=%d out=%q", code, out)
247				}
248			})
249		}
250	}
