273		out, errOut, code := health(t, f,
274			"--node", "reset", "--expected-version", "1.26.0",
275			"--tolerated-misses", "2", "--missed-since-seq", "1")
276		if code != 0 {
277			t.Fatalf("an undecidable miss count is still a successful query: exit=%d stderr=%q", code, errOut)
