398	// strictChecksum replicates the store's checksum over the canonical JSON of a
399	// single record slice, so a test can forge a checksum matching a tampered
400	// interpretation. canonicalJSON must be the store's marshaled record form.
401	func strictChecksum(canonicalJSON string) string {
402		sum := sha256.Sum256([]byte(canonicalJSON))
403		return hex.EncodeToString(sum[:])
404	}
405	
406	// envelope wraps a raw records array in a well-formed store file.
407	func envelope(checksum, recordsJSON string) string {
408		return `{"format":"edgefleet-heartbeats-v1","checksum":"` + checksum + `","records":` + recordsJSON + `}`
409	}
