411	// TestCLIStoredCorruptionRefusedByQueries exercises the user-visible contract:
412	// a saved record with a missing, null or duplicated telemetry field corrupts
413	// the node's data even when the checksum matches the interpreted values; every
414	// query for that node fails on stderr with a non-zero exit and prints nothing
415	// on stdout, while other nodes keep working.
416	func TestCLIStoredCorruptionRefusedByQueries(t *testing.T) {
417		f := newFixture(t)
418	
419		const badRecord = `{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}`
420		submitBatch(t, f.dir, "["+badRecord+"]")
421	
422		cases := []struct {
423			name        string
424			tamper      string // raw records array stored alongside a matching checksum
425			interpreted string // canonical records a lenient reader reconstructs
426			wantField   string
427		}{
428			{
429				name:        "missing missed stays matching with original checksum",
430				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`,
431				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
432				wantField:   "missed",
433			},
434			{
435				name:        "null height with checksum over zero-filled value",
436				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":null,"missed":0}]`,
437				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":0,"missed":0}]`,
438				wantField:   "height",
439			},
440			{
441				name:        "duplicate missed same value, last-wins interpretation matches",
442				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0,"missed":0}]`,
443				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
444				wantField:   "missed",
445			},
446		}
447	
448		for _, tc := range cases {
449			t.Run(tc.name, func(t *testing.T) {
450				// The forged checksum hashes the canonical record a lenient
451				// reader would reconstruct (zero-filled / last value).
452				corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(tc.interpreted), tc.tamper))
453	
454				// history: non-zero exit, explicit reason on stderr naming the
455				// file/record/field, no normal output on stdout.
456				out, errOut, code := runCLI(t, f.dir, "",
457					"heartbeat", "history", "--data-dir", f.dir, "--node", "bad")
458				if code == 0 {
459					t.Errorf("history on corrupt node must exit non-zero; stdout=%q", out)
460				}
461				if out != "" {
462					t.Errorf("history must print no results on corruption, stdout=%q", out)
463				}
464				if !strings.Contains(errOut, "error:") || !strings.Contains(errOut, "record 1") ||
465					!strings.Contains(errOut, tc.wantField) {
466					t.Errorf("history stderr must explain the corrupt record/field, got %q", errOut)
467				}
468				if !strings.Contains(errOut, filepath.Base(nodeFileHexPath(f.dir, "bad"))) {
469					t.Errorf("history stderr should identify the corrupt file, got %q", errOut)
470				}
471	
472				// health: same contract.
473				out, errOut, code = health(t, f,
474					"--node", "bad", "--expected-version", "1.26.0", "--tolerated-misses", "0")
475				if code == 0 {
476					t.Errorf("health on corrupt node must exit non-zero; stdout=%q", out)
477				}
478				if out != "" {
479					t.Errorf("health must print no results on corruption, stdout=%q", out)
480				}
481				if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, tc.wantField) {
482					t.Errorf("health stderr must explain the corrupt record/field, got %q", errOut)
483				}
484	
485				// health with a missed-duty baseline must fail identically rather
486				// than skipping the bad record.
487				out, errOut, code = health(t, f,
488					"--node", "bad", "--expected-version", "1.26.0",
489					"--tolerated-misses", "0", "--missed-since-seq", "1")
490				if code == 0 {
491					t.Errorf("baseline health on corrupt node must exit non-zero; stdout=%q", out)
492				}
493				if out != "" {
494					t.Errorf("baseline health must print no results on corruption, stdout=%q", out)
495				}
496				if !strings.Contains(errOut, tc.wantField) {
497					t.Errorf("baseline health stderr must name the field, got %q", errOut)
498				}
499			})
500		}
501	}
