721		// An emoji written as a surrogate-pair escape is stored under the emoji.
722		out, _, code = runCLI(t, dir,
723			`[{"node":"val-\uD83D\uDE00","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":2,"missed":0}]`,
724			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
725		if code != 0 || !strings.Contains(out, "new=1") {
726			t.Fatalf("surrogate-pair escape must be accepted: code=%d out=%q", code, out)
727		}
728	
729		// Both nodes are queryable by their original ids.
730		out, _, code = runCLI(t, dir, "",
731			"heartbeat", "history", "--data-dir", dir, "--node", "val-�")
732		if code != 0 || !strings.Contains(out, "node=val-� seq=1") {
733			t.Errorf("history for literal replacement char id: code=%d out=%q", code, out)
734		}
735		out, _, code = runCLI(t, dir, "",
736			"heartbeat", "history", "--data-dir", dir, "--node", "val-😀")
737		if code != 0 || !strings.Contains(out, "node=val-😀 seq=1") {
738			t.Errorf("history for emoji id: code=%d out=%q", code, out)
739		}
740	}
741	
742	// submit runs one submit command and returns its full result for inspection.
743	func submit(t *testing.T, dir, json string) (string, string, int) {
744		t.Helper()
745		return runCLI(t, dir, json,
746			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
747	}
748	
749	// history runs the history command for one node.
750	func historyCLI(t *testing.T, dir, node string) (string, string, int) {
751		t.Helper()
752		return runCLI(t, dir, "",
753			"heartbeat", "history", "--data-dir", dir, "--node", node)
754	}
755	
756	// historyLines returns the non-empty history lines for a node.
757	func historyLines(t *testing.T, dir, node string) []string {
758		t.Helper()
759		out, errOut, code := historyCLI(t, dir, node)
760		if code != 0 {
761			t.Fatalf("history for %q exited %d: stderr=%q", node, code, errOut)
762		}
763		return outputLines(out)
764	}
765	
766	// TestCLISubmitMixedBatchCountsNewAndDuplicate drives the example rule end to
767	// end: a batch may mix records already saved, exact repeats within the same
768	// batch, and new records for other nodes. new counts only records genuinely
769	// added this time; duplicate counts every input record that added nothing.
770	// The same seq used by different nodes is never deduplicated across nodes.
771	func TestCLISubmitMixedBatchCountsNewAndDuplicate(t *testing.T) {
772		dir := t.TempDir()
773	
774		// 甲 already has seq 1 saved.
775		submitBatch(t, dir, `[
776		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
777		]`)
778	
779		// Batch: 甲 seq1 again verbatim (duplicate against history), 甲 seq2 twice
780		// identical (one new, one duplicate within the batch), 乙 seq2 (new). The
781		// two nodes share seq 2 but stay distinct records.
782		out, errOut, code := submit(t, dir, `[
783		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0},
784		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
785		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
786		  {"node":"乙","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":201,"missed":2}
787		]`)
788		if code != 0 {
789			t.Fatalf("mixed batch must succeed, exit=%d stderr=%q", code, errOut)
790		}
791		if errOut != "" {
792			t.Errorf("a successful submit must leave stderr empty, got %q", errOut)
793		}
794		if strings.TrimRight(out, "\n") != "submitted: new=2 duplicate=2" {
795			t.Errorf("stdout = %q, want submitted: new=2 duplicate=2", out)
796		}
797	
798		// 甲 history: exactly seq 1 and 2, ascending, original seq-1 telemetry
799		// untouched and seq-2 content as submitted.
800		jia := historyLines(t, dir, "甲")
801		if len(jia) != 2 {
802			t.Fatalf("甲 history = %q, want exactly two records", jia)
803		}
804		want1 := "node=甲 seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=100 missed=0"
805		want2 := "node=甲 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=101 missed=0"
806		if jia[0] != want1 {
807			t.Errorf("甲 first line = %q, want %q", jia[0], want1)
808		}
809		if jia[1] != want2 {
810			t.Errorf("甲 second line = %q, want %q", jia[1], want2)
811		}
812	
813		// 乙 has only its own seq 2; same seq number as 甲 did not dedup.
814		yi := historyLines(t, dir, "乙")
815		if len(yi) != 1 {
816			t.Fatalf("乙 history = %q, want exactly one record", yi)
817		}
818		wantYi := "node=乙 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=201 missed=2"
819		if yi[0] != wantYi {
820			t.Errorf("乙 line = %q, want %q", yi[0], wantYi)
821		}
822	}
823	
824	// TestCLISubmitSameInstantDifferentOffsetIsDuplicate pins the time semantics
825	// of "identical content": the same instant written with another timezone
826	// offset is a duplicate, both within a batch and against saved history.
827	func TestCLISubmitSameInstantDifferentOffsetIsDuplicate(t *testing.T) {
828		dir := t.TempDir()
829	
830		// 11:00:00Z is the same instant as 19:00:00+08:00.
831		out, errOut, code := submit(t, dir, `[
832		  {"node":"n1","seq":1,"collected_at":"2026-10-01T11:00:00Z","version":"1.0","height":10,"missed":0},
833		  {"node":"n1","seq":1,"collected_at":"2026-10-01T19:00:00+08:00","version":"1.0","height":10,"missed":0}
834		]`)
835		if code != 0 {
836			t.Fatalf("same-instant pair inside one batch must be accepted: exit=%d stderr=%q", code, errOut)
837		}
838		if strings.TrimRight(out, "\n") != "submitted: new=1 duplicate=1" {
839			t.Errorf("in-batch timezone-equal record: stdout=%q, want new=1 duplicate=1", out)
840		}
841	
842		// Against saved history, the offset-spelled repeat is still a duplicate.
843		out, errOut, code = submit(t, dir, `[
844		  {"node":"n1","seq":1,"collected_at":"2026-10-01T07:00:00-04:00","version":"1.0","height":10,"missed":0}
845		]`)
846		if code != 0 {
847			t.Fatalf("same-instant resubmit must succeed: exit=%d stderr=%q", code, errOut)
848		}
849		if errOut != "" {
850			t.Errorf("duplicate resubmit must leave stderr empty, got %q", errOut)
851		}
852		if strings.TrimRight(out, "\n") != "submitted: new=0 duplicate=1" {
853			t.Errorf("stdout=%q, want new=0 duplicate=1", out)
854		}
855	
856		lines := historyLines(t, dir, "n1")
857		if len(lines) != 1 {
858			t.Fatalf("history = %q, want the one record with no extra copy", lines)
859		}
860	}
861	
862	// TestCLISubmitContentDifferencesConflictAgainstHistory covers every field
863	// that makes a same-node/same-seq record a conflict rather than a duplicate:
864	// version, height, cumulative missed, and the collection instant (including
865	// equal wall-clock text with a different offset, which is a different
866	// instant). Nothing is overwritten and no last-write-wins occurs.
867	func TestCLISubmitContentDifferencesConflictAgainstHistory(t *testing.T) {
868		const base = `{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}`
869		cases := []struct {
870			name string
871			// incoming is the conflicting record, same node+seq as the saved one.
872			incoming string
873		}{
874			{"version differs",
875				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.27.0","height":100,"missed":0}`},
876			{"height differs",
877				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":101,"missed":0}`},
878			{"missed differs",
879				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":1}`},
880			{"collected instant differs",
881				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:58:00Z","version":"1.26.0","height":100,"missed":0}`},
882			{"same wall clock text, different offset is a different instant",
883				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00+08:00","version":"1.26.0","height":100,"missed":0}`},
884		}
885		for _, tc := range cases {
886			t.Run(tc.name, func(t *testing.T) {
887				dir := t.TempDir()
888				// Each subtest gets its own data directory, so one fixed node id
889				// carrying the saved seq-2 baseline is enough.
890				const node = "node"
891				submitBatch(t, dir, "["+fmt.Sprintf(base, node)+"]")
892				before := historyLines(t, dir, node)
893	
894				out, errOut, code := submit(t, dir, "["+fmt.Sprintf(tc.incoming, node)+"]")
895				if code == 0 {
896					t.Fatalf("conflicting record must fail non-zero; stdout=%q", out)
897				}
898				// The error names the node and the seq, and goes to stderr.
899				for _, want := range []string{"error:", "conflict", node, "seq 2"} {
900					if !strings.Contains(errOut, want) {
901						t.Errorf("stderr %q must contain %q", errOut, want)
902					}
903				}
904				// No success line or counters on stdout.
905				if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
906					t.Errorf("rejected batch must not print success counts, stdout=%q", out)
907				}
908				// The original telemetry is intact: not replaced by the incoming
909				// content, not counted as a duplicate.
910				after := historyLines(t, dir, node)
911				if len(after) != 1 || after[0] != before[0] {
912					t.Errorf("history changed after conflict:\nbefore=%q\nafter =%q", before, after)
913				}
914			})
915		}
916	}
917	
918	// TestCLISubmitConflictWithinBatchRejectsEverything checks the first conflict
919	// condition: two records of the same node+seq with differing content inside
920	// one batch fail the whole batch. Legal records for other nodes — whether
921	// they appear before or after the conflicting pair — must not survive, and a
922	// pre-existing node touched by a legal record in the same batch stays as it
923	// was before the submit.
924	func TestCLISubmitConflictWithinBatchRejectsEverything(t *testing.T) {
925		dir := t.TempDir()
926		// Existing node 旧 with seq 1 already saved.
927		submitBatch(t, dir, `[
928		  {"node":"旧","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":10,"missed":0}
929		]`)
930		oldBefore := readNodeFile(t, dir, "旧")
931	
932		// Batch layout: legal record for a brand-new node 新, then a legal seq-2
933		// for the existing node, then the in-batch conflict on 甲 seq 1, then
934		// another legal new-node record. None of the legal ones may be saved.
935		batch := `[
936		  {"node":"新","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":20,"missed":0},
937		  {"node":"旧","seq":2,"collected_at":"2026-10-01T11:59:20Z","version":"1.0","height":11,"missed":0},
938		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":100,"missed":0},
939		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"2.0","height":100,"missed":0},
940		  {"node":"丙","seq":1,"collected_at":"2026-10-01T11:59:40Z","version":"1.0","height":30,"missed":0}
941		]`
942		out, errOut, code := submit(t, dir, batch)
943		if code == 0 {
944			t.Fatalf("in-batch conflict must fail non-zero; stdout=%q", out)
945		}
946		for _, want := range []string{"error:", "conflict", "甲", "seq 1"} {
947			if !strings.Contains(errOut, want) {
948				t.Errorf("stderr %q must contain %q", errOut, want)
949			}
950		}
951		if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
952			t.Errorf("rejected batch must print no success counts, stdout=%q", out)
953		}
954	
955		// Existing node untouched even though its legal record came first.
956		if got := readNodeFile(t, dir, "旧"); got != oldBefore {
957			t.Errorf("existing node file was modified by the rejected batch")
958		}
959		// Brand-new nodes in the batch must have no history at all.
960		for _, node := range []string{"新", "甲", "丙"} {
961			out, errOut, code := historyCLI(t, dir, node)
962			if code != 0 {
963				t.Fatalf("history query after rejected batch must itself work for %q: %d %q", node, code, errOut)
964			}
965			if strings.TrimRight(out, "\n") != "node="+node+" no heartbeats" {
966				t.Errorf("node %q must have no records after rejected batch, got %q", node, out)
967			}
968			if _, err := os.Stat(nodeFileHexPath(dir, node)); !os.IsNotExist(err) {
969				t.Errorf("no file may be created for node %q, stat err=%v", node, err)
970			}
971		}
972	}
973	
974	// TestCLISubmitConflictWithSavedHistoryRejectsWholeBatch checks the second
975	// conflict condition: a batch record whose node+seq already exists with
976	// different content fails the batch, including legal records placed before
977	// it. After the failure the store keeps accepting ordinary batches, and all
978	// previously saved content stays queryable.
979	func TestCLISubmitConflictWithSavedHistoryRejectsWholeBatch(t *testing.T) {
980		dir := t.TempDir()
981		// 甲 already saved seq 1 with specific telemetry.
982		submitBatch(t, dir, `[
983		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
984		]`)
985		jiaBefore := readNodeFile(t, dir, "甲")
986	
987		// Legal record for a new node FIRST, then the conflict against saved
988		// history, then another legal new-node record.
989		batch := `[
990		  {"node":"乙","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":200,"missed":1},
991		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"9.9.9","height":100,"missed":0},
992		  {"node":"丙","seq":1,"collected_at":"2026-10-01T11:59:20Z","version":"1.0","height":300,"missed":2}
993		]`
994		out, errOut, code := submit(t, dir, batch)
995		if code == 0 {
996			t.Fatalf("history conflict must fail non-zero; stdout=%q", out)
997		}
998		for _, want := range []string{"error:", "conflict", "甲", "seq 1"} {
999			if !strings.Contains(errOut, want) {
1000				t.Errorf("stderr %q must contain %q", errOut, want)
1001			}
1002		}
1003		if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
1004			t.Errorf("rejected batch must print no success counts, stdout=%q", out)
1005		}
1006	
1007		// 甲 history is byte-identical to before the attempt.
1008		if got := readNodeFile(t, dir, "甲"); got != jiaBefore {
1009			t.Errorf("saved node file was modified by the conflicting batch")
1010		}
1011		// The legal new-node records must not have landed.
1012		for _, node := range []string{"乙", "丙"} {
1013			out, _, _ := historyCLI(t, dir, node)
1014			if strings.TrimRight(out, "\n") != "node="+node+" no heartbeats" {
1015				t.Errorf("node %q must have no records after rejected batch, got %q", node, out)
1016			}
1017			if _, err := os.Stat(nodeFileHexPath(dir, node)); !os.IsNotExist(err) {
1018				t.Errorf("no file may be created for node %q, stat err=%v", node, err)
1019			}
1020		}
1021	
1022		// After the conflict failure, a non-conflicting batch succeeds normally,
1023		// including a genuine new seq for 甲 and the previously rejected node.
1024		out, errOut, code = submit(t, dir, `[
1025		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:40Z","version":"1.26.0","height":102,"missed":0},
1026		  {"node":"乙","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":200,"missed":1}
1027		]`)
1028		if code != 0 {
1029			t.Fatalf("legal batch after a conflict failure must still succeed: exit=%d stderr=%q", code, errOut)
1030		}
1031		if strings.TrimRight(out, "\n") != "submitted: new=2 duplicate=0" {
1032			t.Errorf("recovery submit stdout=%q, want new=2 duplicate=0", out)
1033		}
1034	
1035		// 甲 keeps the original seq-1 content (not the conflict's) and gains the
1036		// new seq 2, ascending.
1037		jia := historyLines(t, dir, "甲")
1038		if len(jia) != 2 {
1039			t.Fatalf("甲 history = %q, want seq 1 and 2", jia)
1040		}
1041		if jia[0] != "node=甲 seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=100 missed=0" {
1042			t.Errorf("original 甲 seq 1 telemetry altered: %q", jia[0])
1043		}
1044		if jia[1] != "node=甲 seq=2 collected_at=2026-10-01T11:59:40Z version=1.26.0 height=102 missed=0" {
1045			t.Errorf("new 甲 seq 2 line = %q", jia[1])
1046		}
1047	}
