		"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
	if code != 0 || !strings.Contains(out, "new=1") {
		t.Fatalf("surrogate-pair escape must be accepted: code=%d out=%q", code, out)
	}

