		"heartbeat", "history", "--data-dir", dir, "--node", "val-�")
	if code != 0 || !strings.Contains(out, "node=val-� seq=1") {
		t.Errorf("history for literal replacement char id: code=%d out=%q", code, out)
	}
	out, _, code = runCLI(t, dir, "",
		"heartbeat", "history", "--data-dir", dir, "--node", "val-😀")
