	if !strings.Contains(line, `version="1.0[2J"`) {
		t.Errorf("version escape must display as : %q", line)
	}
	if !strings.Contains(line, `version skew: "1.0[2J" != 1.0`) {
		t.Errorf("skew finding must use the same display rule: %q", line)
	}

	// The stored record keeps the original bytes; the display form is never
	// written back.
	raw := readNodeFile(t, dir, "n1")
	if !strings.Contains(raw, `"version":"1.0[2J"`) {
